 */
scwin.btn_SDATE_onclick = function() {
    try {
        popUpCalendar2(edt_SDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26500.btn_SDATE_onclick" });
    }
};

/**
