};

/**
 * @method
 * @name cmb_UPCLSS_onselchange
 * @description cmb_UPCLSS onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_UPCLSS_onselchange = async function() {
    try {
        await scwin.getClassByUpClass();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26500.cmb_UPCLSS_onselchange" });
    }
};

/**
 * @method
 * @name rdo_MKT_ID_onselchange
 * @description rdo_MKT_ID onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_MKT_ID_onselchange = function() {
    // fn_SetCtrlByMktId();

};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26500.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadError
 * @description dts_Grid 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Grid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26500.dts_Grid_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    try {
        if (scwin.vCurrPageNo === 0) {
            scwin.vCurrPageNo = 1;
        }
        const vTotalCnt = dts_Grid.getCellData(1, "CNT");
        // alert("vTotalCnt=" + vTotalCnt);
        $c.stf.FillGridHeader2(scwin.pageNoCnt, cmb_PerPage.getValue(), vTotalCnt, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26500.dts_Grid_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = cmb_PeriodTp.getValue();
        $c.stf.setFromToDate(vTp, edt_SDATE, edt_EDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26500.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name cmb_PerPage_onselchange
 * @description cmb_PerPage onselchange 이벤트
 * @returns {void}
