    try {
        await scwin.toExcel();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26500.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name dts_ForExcel_OnLoadCompleted
 * @description dts_ForExcel 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_ForExcel_OnLoadCompleted = function(rowcount) {
    try {
        $c.data.downloadGridViewExcel(grd_ForExcel, {fileName: "공시건수현황", sheetName: "c:\abs\test.xls", type: 16});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26500.dts_ForExcel_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_ForExcel_OnLoadError
 * @description dts_ForExcel 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ForExcel_OnLoadError = async function() {
    try {
        await $c.win.alert("엑셀 저장에 실패하였습니다.");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26500.dts_ForExcel_OnLoadError" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        if (colid === "COM_NM") {
            scwin.gIsurCd = dts_Grid.getCellData(row, "ISUR_CD");
            $c.stf.fn_PopupCorpInfo();
        } else if (colid === "FORM_KOR_NM") {
            const vAcptNo = dts_Grid.getCellData(row, "ACPT_NO");
            await $c.stf.openDisclViewer(vAcptNo, "R");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26500.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26500.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26500.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26500.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26500.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26500.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26500.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onfocus
 * @description txb_ISUR_CD 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26500.txb_ISUR_CD_onfocus" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else return true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26500.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onkeyup
 * @description txb_ISUR_CD 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onkeyup = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26500.txb_ISUR_CD_onkeyup" });
    }
};

/**
 * @method
 * @name rdo_DISCLS_TYPE_onclick
 * @description rdo_DISCLS_TYPE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_DISCLS_TYPE_onclick = function() {
    try {
        const value = rdo_DISCLS_TYPE.getValue();
        if (value === '1') {
            cmb_DISCLS_TP_CLSS.setDisabled(true);
            cmb_DISCLS_RSN_CLSS.setDisabled(true);
            cmb_DISCLS_RSN_CLSS.setSelectedIndex('0');
        } else {
            cmb_DISCLS_TP_CLSS.setDisabled(true);
            cmb_DISCLS_TP_CLSS.setSelectedIndex('0');
            cmb_DISCLS_RSN_CLSS.setDisabled(true);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26500.rdo_DISCLS_TYPE_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
