/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    const argv = scwin.search.arguments;
    const argc = scwin.search.arguments.length;
    let vPAGENO = (argc === 0) ? 0 : vPAGENO = argv[0];
    let vSDATE = edt_SDATE.getValue();
    let vEDATE = edt_EDATE.getValue();
    if (vSDATE === "" || vEDATE === "") {
        await $c.win.alert("[기간]을 선택하세요.");
        return; // 처리시각
    }
    let vF = chb_F.getValue();
    let vM = chb_M.getValue();
    let vA = chb_A.getValue();
    let vU = chb_U.getValue();
    if (vF === "N" && vM === "N" && vA === "N" && vU === "N") {
        chb_F.setValue("Y");
        chb_M.setValue("Y");
    }
    url += "&MKT_ID=" + rdo_MKT_ID.getValue();
    url += "&SDATE=" + vSDATE;
    url += "&EDATE=" + vEDATE;
    url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
    url += "&SUBMIT_F=" + chb_F.getValue();
    url += "&SUBMIT_M=" + chb_M.getValue();
    url += "&SUBMIT_A=" + chb_A.getValue();
    url += "&SUBMIT_U=" + chb_U.getValue();
    url += "&FORM_UPCLSS_CD=" + cmb_UPCLSS.getValue();
    url += "&TP_CLSS_CD=" + cmb_DISCLS_TP_CLSS.getValue();
    url += "&RSN_CLSS_CD=" + cmb_DISCLS_RSN_CLSS.getValue();
    url += "&COM_TP_CD=" + cmb_COMPANY_ATTRIBUTE.getValue();
    url += "&PAGENO=" + vPAGENO;
    url += "&PAGESIZE=" + cmb_PerPage.getValue();
    url += "&SCREN_ID=" + 'ULDSTF26500.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    // alert(url);
    const sbmOptions = {
        id : "sbm_dts_Grid",
        action : "/DisclosureCountStatistics.do",
        ref : "",
        target : "dts_Grid=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name toExcel
 * @description to Excel 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.toExcel = async function() {
    let vSDATE = edt_SDATE.getValue();
    let vEDATE = edt_EDATE.getValue();
    if (vSDATE === "" || vEDATE === "") {
        await $c.win.alert("[기간]을 선택하세요.");
        return; // 처리시각
    }
    let vF = chb_F.getValue();
    let vM = chb_M.getValue();
    let vA = chb_A.getValue();
    let vU = chb_U.getValue();
    if (vF === "N" && vM === "N" && vA === "N" && vU === "N") {
        chb_F.setValue("Y");
        chb_M.setValue("Y");
    }
    url += "&MKT_ID=" + rdo_MKT_ID.getValue();
    url += "&SDATE=" + vSDATE;
    url += "&EDATE=" + vEDATE;
    url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
    url += "&SUBMIT_F=" + chb_F.getValue();
    url += "&SUBMIT_M=" + chb_M.getValue();
    url += "&SUBMIT_A=" + chb_A.getValue();
    url += "&SUBMIT_U=" + chb_U.getValue();
    url += "&FORM_UPCLSS_CD=" + cmb_UPCLSS.getValue();
    url += "&TP_CLSS_CD=" + cmb_DISCLS_TP_CLSS.getValue();
    url += "&RSN_CLSS_CD=" + cmb_DISCLS_RSN_CLSS.getValue();
    url += "&COM_TP_CD=" + cmb_COMPANY_ATTRIBUTE.getValue();
    url += "&PAGENO=1";
    url += "&PAGESIZE=0"; // 전체.
    url += "&SCREN_ID=" + 'ULDSTF26500.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_07;
    const sbmOptions = {
        id : "sbm_dts_ForExcel",
        action : "/DisclosureCountStatistics.do",
        ref : "",
        target : "dts_ForExcel=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

